CREATE TABLE r AS SELECT a,b,sum(c)OVER(ORDER BY a GROUPS BETWEEN 3 PRECEDING AND 0 PRECEDING EXCLUDE CURRENT ROW) AS x1,sum(c)OVER(ORDER BY a GROUPS BETWEEN 3 PRECEDING AND 0 PRECEDING) AS x2,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN 3 PRECEDING AND 0 PRECEDING EXCLUDE CURRENT ROW) AS x3,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN 3 PRECEDING AND 0 PRECEDING) AS x4 FROM t3;